// Groupe « nord » : États-Unis (US), Canada (CA), Groenland (GL), Bermudes (BM).
// Recherches et vérification contre public/data/communes-xx.txt : 16 septembre 2026.
// Taux InforEuro septembre 2026 : 1 EUR = 1,1643 USD = 1,613 CAD (SPM Ferries facture en euros).
//
// Masses : `northAmerica` (continent relié par la route, Alaska routier compris via l'Alaska Highway), `newfoundland`,
// `vancouverIsland`, etc. Les îles reliées par pont, chaussée ou tunnel ne reçoivent AUCUNE règle et restent
// northAmerica : Long Island, Staten Island, Aquidneck, Conanicut, Mount Desert, Deer Isle, Chincoteague, Outer Banks
// (pont Marc Basnight vers Hatteras), Keys (Overseas Highway), Sanibel/Captiva, Galveston, South Padre, Grand Isle,
// Dauphin Island, Whidbey (Deception Pass), Camano, Bainbridge (Agate Pass), Fox Island, Marrowstone, Mercer Island,
// Coronado, Alameda, îles du lac Champlain (Grand Isle, North Hero, Isle La Motte), Grosse Ile, Wellesley (Mille-Îles),
// Campobello (pont Roosevelt vers Lubec), Île-du-Prince-Édouard (pont de la Confédération), Cap-Breton (chaussée de
// Canso), Isle Madame, Lamèque et Miscou, Manitoulin (pont tournant de Little Current), St. Joseph Island, Île d'Orléans,
// Hecla, New World Island et Twillingate (chaussées), etc.
// Enclaves sans route isolées (clé '*' ou clé nommée quand un ferry véhicules les dessert) : villages d'Alaska, Juneau,
// Nunavut, Nunavik, nord de l'Ontario et du Manitoba, TNO hors réseau, côte nord du Labrador, Basse-Côte-Nord…
//
// Convention de prix : EUR ; classe 1 = voiture seule (conducteur déduit quand le tarif l'inclut), 2 = camping-car ou
// fourgon (catégorie précisée dans chaque note), 5 = moto seule, foot = passager adulte ; une traversée (tarif
// aller-retour perçu une seule fois → moitié). Durées et distances : publiées quand indiqué, sinon ordres de grandeur
// (distance orthodromique entre ports, vitesse commerciale usuelle du navire).
const D = '2026-09-16';
const USD = 1.1643, CAD = 1.613;
const r2 = v => Math.round(v * 100) / 100;
const u = v => (v == null ? null : r2(v / USD));
const c = v => (v == null ? null : r2(v / CAD));
const US = (car, camper, moto, foot) => ({ 1: u(car), 2: u(camper), 5: u(moto), foot: u(foot) });
const CA = (car, camper, moto, foot) => ({ 1: c(car), 2: c(camper), 5: c(moto), foot: c(foot) });
const UNKNOWN = { 1: null, 2: null, 5: null, foot: null };
const FREE = { 1: 0, 2: 0, 5: 0, foot: 0 };
// BC Ferries (Fare Index v26-05, en vigueur le 16 juin 2026) : véhicule ≤ 20 pi hors conducteur, + tarif par pied
// au-delà ; classe 2 = véhicule de 22 pi (6,7 m) ; +5 % de surtaxe carburant appliquée au paiement ;
// `ret` = tarif aller-retour perçu au départ du continent ou de la grande île (moitié par traversée).
const bcf = (car, perFt, moto, adult, ret) => { const f = 1.05 * (ret ? 0.5 : 1); return CA(car * f, (car + 2 * perFt) * f, moto * f, adult * f); };
const BCF_SRC = 'https://www.bcferries.com/web_image/h90/h4b/9089486028830.pdf';
const AMHS_SRC = 'https://dot.alaska.gov/amhs/route.shtml';
const AMHS_NOTE = "Alaska Marine Highway System, horaire d'été 2026 (1er mai–30 septembre ; port listé dans le plan de déploiement « Summer 2026 », https://dot.alaska.gov/amhs/doc/summer-considerations-2026.pdf). Véhicules transportés. Aucune grille publiée : les tarifs ne s'obtiennent que par le moteur de réservation « Sailing Search » (https://dot.alaska.gov/amhs/fares.shtml) → priceStatus 'unknown'. ";
